export type ContentDashboardSummaryResponse = {
    /**
     * Number of sitemaps checked in this run
     */
    sitemapsChecked: number;
    /**
     * Number of sitemaps successfully processed
     */
    sitemapsSuccessful: number;
    /**
     * Your domain's content metrics
     */
    customer: ContentSummaryCustomerResponse;
    /**
     * Competitor with the most strategic URLs, or null when no competitor returned usable content data this run — that is the only thing null means here, and it never means the competitors have none. A competitor leading with `strategicUrls: 0` is the opposite case and is a real result: everyone was measured and nobody publishes a strategic page.
     */
    topCompetitor?: ContentSummaryTopCompetitorResponse | null;
    /**
     * Your strategic URL count minus the top competitor's (negative = you are behind), or null when there is no comparison to make: your own sitemap was unmeasured, or no competitor returned usable content data. A 0 means genuinely level. Was a forced 0 before, which read as 'level with them' either way. A gap equal to your own count is what a measured field of zeros produces — your largest possible lead, and a finding to report rather than an anomaly to explain away.
     */
    strategicUrlGap: number | null;
    /**
     * Your rank by strategic content among the sites that returned comparable content data — your own site plus `comparableCompetitors` competitors (field size = comparableCompetitors + 1). Null when fewer than two competitors had usable data, or when your own site returned no usable data to rank.
     */
    overallRank?: number | null;
    /**
     * Competitors (excluding your own site) that returned usable content data — the sample size behind the gap and advantage comparisons. The overall rank is taken over this set plus your own site, so the rank's field size is `comparableCompetitors + 1`.
     */
    comparableCompetitors: number;
    /**
     * Content categories where you have zero content but competitors do. Only the 9 strategic categories are evaluated here: Blog Posts, Documentation, Free Tools, Landing Pages, Case Studies, Comparison Pages, Integrations, Changelog, Webinars. Legal, Programmatic Pages, Other are counted in `categorizedCounts` but never assessed, so their absence from this list is not a verdict about them. Null in TWO cases, and they are different facts you must not report as the same one: your own sitemap couldn't be analyzed this run (`customer.contentAnalysisAvailable` is present — our reach into YOUR site), or no competitor returned usable content data (`comparableCompetitors` is 0 — our reach into THEIRS, with your own site measured fine). Check both before saying whose check failed. An empty array is neither: it means we compared and found none, which is a real finding.
     */
    criticalGaps: Array<ContentCriticalGapResponse> | null;
    /**
     * Content categories where you are significantly behind (>50%). Only the 9 strategic categories are evaluated here: Blog Posts, Documentation, Free Tools, Landing Pages, Case Studies, Comparison Pages, Integrations, Changelog, Webinars. Legal, Programmatic Pages, Other are counted in `categorizedCounts` but never assessed, so their absence from this list is not a verdict about them. Null in TWO cases, and they are different facts you must not report as the same one: your own sitemap couldn't be analyzed this run (`customer.contentAnalysisAvailable` is present — our reach into YOUR site), or no competitor returned usable content data (`comparableCompetitors` is 0 — our reach into THEIRS, with your own site measured fine). Check both before saying whose check failed. An empty array is neither: it means we compared and found none, which is a real finding.
     */
    significantGaps: Array<ContentSignificantGapResponse> | null;
    /**
     * Content categories where you lead all competitors. Only the 9 strategic categories are evaluated here: Blog Posts, Documentation, Free Tools, Landing Pages, Case Studies, Comparison Pages, Integrations, Changelog, Webinars. Legal, Programmatic Pages, Other are counted in `categorizedCounts` but never assessed, so their absence from this list is not a verdict about them. A category missing from this list either wasn't evaluated or wasn't led — check it against that set before reporting either. Null in TWO cases, and they are different facts you must not report as the same one: your own sitemap couldn't be analyzed this run (`customer.contentAnalysisAvailable` is present — our reach into YOUR site), or no competitor returned usable content data (`comparableCompetitors` is 0 — our reach into THEIRS, with your own site measured fine). Check both before saying whose check failed. An empty array is neither: it means we compared and found none, which is a real finding. A null here in particular must NOT be read as leading in none.
     */
    advantages: Array<ContentAdvantageResponse> | null;
    /**
     * Content categories where you are competitive (within threshold). Only the 9 strategic categories are evaluated here: Blog Posts, Documentation, Free Tools, Landing Pages, Case Studies, Comparison Pages, Integrations, Changelog, Webinars. Legal, Programmatic Pages, Other are counted in `categorizedCounts` but never assessed, so their absence from this list is not a verdict about them. Null in TWO cases, and they are different facts you must not report as the same one: your own sitemap couldn't be analyzed this run (`customer.contentAnalysisAvailable` is present — our reach into YOUR site), or no competitor returned usable content data (`comparableCompetitors` is 0 — our reach into THEIRS, with your own site measured fine). Check both before saying whose check failed. An empty array is neither: it means we compared and found none, which is a real finding.
     */
    onTrack: Array<ContentOnTrackResponse> | null;
    /**
     * Total number of critical content gaps, out of the 9 strategic categories evaluated. Derived from the list above, so the two are always consistent — including when both are null. Null in TWO cases, and they are different facts you must not report as the same one: your own sitemap couldn't be analyzed this run (`customer.contentAnalysisAvailable` is present — our reach into YOUR site), or no competitor returned usable content data (`comparableCompetitors` is 0 — our reach into THEIRS, with your own site measured fine). Check both before saying whose check failed. An empty array is neither: it means we compared and found none, which is a real finding.
     */
    totalCriticalGaps: number | null;
    /**
     * Total number of significant content gaps, out of the 9 strategic categories evaluated. Derived from the list above, so the two are always consistent. Null in TWO cases, and they are different facts you must not report as the same one: your own sitemap couldn't be analyzed this run (`customer.contentAnalysisAvailable` is present — our reach into YOUR site), or no competitor returned usable content data (`comparableCompetitors` is 0 — our reach into THEIRS, with your own site measured fine). Check both before saying whose check failed. An empty array is neither: it means we compared and found none, which is a real finding.
     */
    totalSignificantGaps: number | null;
    /**
     * Total number of content advantages, out of the 9 strategic categories evaluated. Derived from the list above, so the two are always consistent. Null in TWO cases, and they are different facts you must not report as the same one: your own sitemap couldn't be analyzed this run (`customer.contentAnalysisAvailable` is present — our reach into YOUR site), or no competitor returned usable content data (`comparableCompetitors` is 0 — our reach into THEIRS, with your own site measured fine). Check both before saying whose check failed. An empty array is neither: it means we compared and found none, which is a real finding.
     */
    totalAdvantages: number | null;
    /**
     * Total number of on-track categories, out of the 9 strategic categories evaluated. Derived from the list above, so the two are always consistent. Null in TWO cases, and they are different facts you must not report as the same one: your own sitemap couldn't be analyzed this run (`customer.contentAnalysisAvailable` is present — our reach into YOUR site), or no competitor returned usable content data (`comparableCompetitors` is 0 — our reach into THEIRS, with your own site measured fine). Check both before saying whose check failed. An empty array is neither: it means we compared and found none, which is a real finding.
     */
    totalOnTrack: number | null;
};

export type ContentCompetitorUnavailableResponse = {
    /**
     * Always false — present only when this competitor row carries no content data
     */
    available: boolean;
    /**
     * Why this competitor's content couldn't be counted this run. 'no_sitemap_published' = no working sitemap was found for them — nothing was discovered, or every location we know of returns 404. Read it as 'nothing findable where we look', not as proof they publish none: we re-discover sitemap locations periodically, so a competitor who has MOVED theirs reads this way until we re-check. What it does support is that their content is currently invisible to sitemap-based analysis, and to sitemap-reading crawlers. 'sitemap_fetch_failed' = our fetch or parse failed this run — nothing was measured, so no verdict about the competitor's content may be derived from this row. On the dashboard this reflects the latest known fetch state — a newer run's in-flight failure can briefly surface here until that run completes; in run-detail responses the reason is scoped to that run.
     */
    reason: 'no_sitemap_published' | 'sitemap_fetch_failed';
};

export type ContentCompetitorResponse = {
    /**
     * Competitor domain
     */
    domain: string;
    /**
     * Whether this is the project's own domain
     */
    isOwn: boolean;
    /**
     * Total DISTINCT URLs across this competitor's sitemaps, or null exactly when `contentDataAvailable` is present (no readable sitemap this run). Never read a null as 0: '0 URLs' is a measured claim about a readable sitemap. Distinct matters and is not a formality — two of a competitor's stored sitemap locations can resolve to the same set of pages after they reorganise, and each page is counted once regardless. So this figure need not equal the sum of the per-sitemap counts you may see elsewhere, and `sitemapCount` counts the files they publish rather than the ones that contributed here. Do not reconcile the two; this is the page count.
     */
    totalUrls: number | null;
    /**
     * Strategic URLs — the sum over the 9 strategic categories ONLY. Legal, Programmatic Pages, Other are counted in `categorizedCounts` and excluded here, so `totalUrls - strategicUrls` is NOT "legal plus junk" — most of it may be Programmatic Pages, which is a content operation rather than noise. Null exactly when `contentDataAvailable` is present.
     */
    strategicUrls: number | null;
    /**
     * URL counts by content category, or null if categorization unavailable. Keys are the 12 categories we classify into: blog, docs, tools, landing, caseStudies, comparison, integrations, changelog, webinars, legal, programmatic, other. A category ABSENT from the map was not computed for this run — older runs predate categories added since — while a category present with `0` was measured as empty. Those are different facts; do not report an absent key as a zero.
     */
    categorizedCounts?: {
        [key: string]: number;
    } | null;
    /**
     * Up to 5 real URLs sampled from this competitor's `programmatic` pages, spread across the sections they came from. Empty where this row's `programmatic` count is 0.
     *
     * Why these ship: the platform reports templated pages WITHOUT judging why a vendor generates them, because a URL shape cannot show intent — for a programmatic-SEO player it is the growth engine, for a reference database it is plumbing. That refusal is only honest if you can settle it yourself, and these URLs do that in seconds. **Open two or three before characterising a large `programmatic` count.** They are evidence for a count, not a measurement of their own — sampled at read time, never stored, so they may differ between calls.
     *
     * `null` exactly when `contentDataAvailable` is present: we read no sitemap, so there is nothing to sample. An empty ARRAY means `categorizedCounts.programmatic` is 0 across the sitemaps this row counts — read the two together, and never read an empty array as a stronger claim than that count.
     */
    programmaticExampleUrls: Array<string> | null;
    /**
     * Number of READABLE sitemaps this run for this competitor (0 when `contentDataAvailable` is present)
     */
    sitemapCount: number;
    /**
     * Honest-degradation discriminator (per-competitor). Present only when NO sitemap could be read for this competitor this run — see `reason` for whether that is a measured absence (no working sitemap could be found for them, a claim whose limits `reason` spells out) or our fetch failure. When present, `totalUrls` and `strategicUrls` are null and `categorizedCounts` is null — do not derive any content verdict (e.g. 'competitor has no blog') from this row. Absent whenever at least one sitemap was read (the normal path). On the dashboard, rows reflect the latest known state per sitemap, so a fetch failure in a newer, still-running run can briefly mark a row unavailable until that run completes; run-detail rows are scoped to their own run.
     */
    contentDataAvailable?: ContentCompetitorUnavailableResponse;
};

